$_MODULE['<{lggooglereviews}prestashop>help_3612879708f67ddbaffef6b85b8a7721'] = 'Nel campo \"Recensioni da mostrare\" è possibile scegliere il numero di blocchi da mostrare contemporaneamente nel cursore';
$_MODULE['<{lggooglereviews}prestashop>help_a8a22f09149459a347b30e8005ab34f4'] = 'I \"Rich Snippet\" sono un insieme di tag non visibili ai vostri clienti, ma utilizzati dai motori di ricerca per raccogliere informazioni dalle loro opinioni. Se volete facilitare ai motori di ricerca l\'ottenimento di queste informazioni, selezionate \"Sì\".';
$_MODULE['<{lggooglereviews}prestashop>help_dee2ff8dd3e1feec8bb332b79163a1a4'] = 'L\'opzione \"Mostra intestazione\" includerà all\'inizio del blocco un\'intestazione in cui è possibile mostrare i dati dell\'azienda, quali: il nome, l\'immagine, le valutazioni e i link al profilo in Google Places.';
$_MODULE['<{lggooglereviews}prestashop>help_554d5ff6ac027319ca16bf76c83c6095'] = '\"Mostra l\'immagine dell\'intestazione\" includerà l\'immagine associata alla vostra azienda se l\'avete caricata e, in caso contrario, l\'icona predefinita che avete definito in Google My Business.';
$_MODULE['<{lggooglereviews}prestashop>help_bc1b4b599ba23e1aaeda1e0d4de99c3b'] = '\"Mostra il link alla pagina Google My Business della tua azienda\" mostrerà un link al tuo profilo aziendale su Google My Business.';
$_MODULE['<{lggooglereviews}prestashop>help_ee27a2fa1a14965f274765a67e5a8924'] = '\"Mostra link a [Vedi tutte le recensioni]\" mostrerà un link con cui i clienti potranno accedere all\'elenco completo delle recensioni su Google My Business.';
$_MODULE['<{lggooglereviews}prestashop>help_559358899352d23a924ba8782fd364dc'] = '\"Mostra link a [Aggiungi recensione]\" visualizzerà un link per invitare i clienti a lasciare una recensione sulla vostra attività.';
$_MODULE['<{lggooglereviews}prestashop>help_1ef8624b78f3fd5b154773974b2f2dac'] = 'Se avete scelto l\'opzione precedente, dovete includere l\'url dell\'invito. Nella sezione \"Richiesta di recensioni\" della guida viene spiegato come ottenerlo';
$_MODULE['<{lggooglereviews}prestashop>help_85cd03234f067e40d64fe6c28797fa67'] = 'Indicare se si desidera visualizzare il messaggio \"Powered by Google\".';
