$_MODULE['<{lggooglereviews}prestashop>help_3203e573a77f0fd7c5948c3d846abc52'] = 'Indicare se si vuole mostrare il numero di recensioni ottenute in Google my Business';
$_MODULE['<{lggooglereviews}prestashop>help_bfd47e79bf08ab639511bf993139b22e'] = 'Se si desidera visualizzare l\'elenco delle ultime recensioni ricevute, selezionare l\'opzione';
$_MODULE['<{lggooglereviews}prestashop>help_a481969fefacd2cac4651bc0cad8ace8'] = 'Indicare se si desidera mostrare un link al profilo degli utenti che hanno lasciato una recensione.';
$_MODULE['<{lggooglereviews}prestashop>help_4e7c6bc487018fc97dc555c507a10cc0'] = 'Esaminare i dati aziendali';
$_MODULE['<{lggooglereviews}prestashop>help_367c548945a796b5e52169e33b27202b'] = 'Nella scheda \"Statistiche\" è possibile visualizzare un riepilogo statistico dei dati della propria attività in Google My Business.';
$_MODULE['<{lggooglereviews}prestashop>help_b1e986d1a578a5ff89bedf9d5e52b012'] = 'Per utilizzare le API di Google Maps e Places, è necessario registrare l\'applicazione e ottenere una chiave API. Probabilmente lo sapete già, ma vi spieghiamo come ottenere questa chiave se non lo sapete.';
$_MODULE['<{lggooglereviews}prestashop>help_929457b0d047a741db5a051fb3409dab'] = 'Come creare la CHIAVE API di Google Maps';
$_MODULE['<{lggooglereviews}prestashop>help_9620b9481e88199f573c9800e8f2a621'] = 'Seguire le istruzioni riportate di seguito per creare una CHIAVE API.';
$_MODULE['<{lggooglereviews}prestashop>help_45887556e1cc6a572c574708e1676ea6'] = 'È necessario accedere con il proprio account gmail o creare un nuovo account gmail da associare al progetto.';
$_MODULE['<{lggooglereviews}prestashop>help_b4c1815fa181e8d36cba075fb5ea51b8'] = 'Una volta effettuato l\'accesso, si deve andare alla console di Google Cloud Platform:';
$_MODULE['<{lggooglereviews}prestashop>help_6b05e59b1c6f2513ea4ec8811602146c'] = 'Nel menu di sinistra, si accede alla sezione APIS e servizi.';
$_MODULE['<{lggooglereviews}prestashop>help_7622adcc5af6e55d3a7667c19c13a6fb'] = 'Scrivete il nome del progetto e fate clic sul pulsante \"CREA\".';
$_MODULE['<{lggooglereviews}prestashop>help_55fd75e5be5f25af27c8e67eb2faa100'] = 'Successivamente, facciamo clic sul pulsante \"ABILITA APIS E SERVIZI\".';
$_MODULE['<{lggooglereviews}prestashop>help_fc45981f4bf623a93720e128bc1a1c10'] = 'In questo caso, selezionare \"LUOGHI API\".';
$_MODULE['<{lggooglereviews}prestashop>help_7684dbca91a174e239e2a8d062df29b1'] = 'Fare clic sul pulsante \"ABILITA\".';
$_MODULE['<{lggooglereviews}prestashop>help_824a6c6060cae1ce4265e018736337df'] = 'Una volta creata l\'API, nella scheda \"Credenziali\". Cliccare sul link \"Credenziali in API e servizi\".';
$_MODULE['<{lggooglereviews}prestashop>help_04ee3b1cdc9f4b27e27ec84255924905'] = 'Copiare la chiave API visualizzata sullo schermo, perché ci servirà in seguito.';
$_MODULE['<{lggooglereviews}prestashop>help_ebc72db384475b19cabb579e57785996'] = 'Nella stessa finestra pop-up è possibile scegliere l\'opzione \"Limita password\". Fare clic su questo link se si desidera che la chiave sia utilizzata solo in un determinato dominio, ad esempio.';
$_MODULE['<{lggooglereviews}prestashop>help_449abc375ecc691847413fbc9d739a59'] = 'Una volta ristretta la password, se lo desiderate, dovremo inserire i dati di fatturazione perché, in caso contrario, saremo autorizzati a chiamare questa API solo una volta al giorno e, sinceramente, spero che il vostro sito web abbia più di una visita al giorno. Questo non significa che ci verrà addebitato qualcosa, poiché Google offre questo servizio gratuitamente per un numero elevato di chiamate all\'API, un numero per il quale una PMI normalmente non deve pagare. Se superate il numero di visualizzazioni che Google vi offre gratuitamente, è probabile che l\'attività stia andando molto, molto bene e che non abbiate problemi a investire un po\' in questo senso. Anche se non lo superate, Google vi chiede i dati di fatturazione nel caso in cui ciò avvenga prima o poi. D\'altra parte, per la vostra tranquillità, vi dico che Google vi permette di porre un limite alle chiamate alla sua API al mese. Pertanto, potete limitare il numero di chiamate gratuite al mese e, quindi, non vi verrà mai addebitato nulla; semplicemente, le opinioni verranno interrotte se superate tale numero.';
$_MODULE['<{lggooglereviews}prestashop>help_fb9ad09694f5986566d455aca68450a9'] = 'Come inserire i dati di fatturazione?';
$_MODULE['<{lggooglereviews}prestashop>help_719545827e174b52f5007290935e39e1'] = 'Seguire le istruzioni riportate di seguito per inserire i dati di fatturazione.';
$_MODULE['<{lggooglereviews}prestashop>help_78a42223fc0bf73ebd95dea4c186874f'] = 'Nella console di Google Cloud Platform, se facciamo clic sull\'icona del menu con 3 linee orizzontali, che si trova all\'estrema sinistra, apparirà il menu di navigazione. Lì dobbiamo fare clic sulla voce \"Fatturazione\".';
$_MODULE['<{lggooglereviews}prestashop>help_17bdf9283a5ae0b5df854db1dd3dd7c9'] = 'Faremo clic sul pulsante \"Gestisci conti di fatturazione\".';
$_MODULE['<{lggooglereviews}prestashop>help_d854108423e34b73cf5b3537c4e74e69'] = 'Clicchiamo sul pulsante \"Aggiungi account di fatturazione\" e seguiamo i passaggi indicati da Google, inserendo le informazioni richieste.';
$_MODULE['<{lggooglereviews}prestashop>help_b04a7d3f4f74a068e64d49e24b110c76'] = 'Selezionare il profilo di Google Payments che sarà associato a questo conto di fatturazione. È possibile selezionare un profilo esistente o crearne uno nuovo.';
